#!/usr/bin/env python3\n\"\"\"\nSimple Adaptive Test\n===================\nSimplified test to validate the core adaptive system components work.\n\"\"\"\n\nimport sys\nimport os\nimport logging\nfrom datetime import datetime\n\n# Add src to path\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), 'src'))\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\ndef test_core_components():\n    \"\"\"Test individual core components\"\"\"\n    \n    print(\"🧪 Testing Core Components\")\n    print(\"=\" * 30)\n    \n    # Test 1: Confidence Manager\n    try:\n        from src.core.confidence_manager import ReactiveConfidenceManager\n        confidence_mgr = ReactiveConfidenceManager()\n        \n        # Add a test confidence event\n        event_id = confidence_mgr.add_confidence_event(\n            symbol=\"TEST\",\n            initial_confidence=0.8,\n            source_strategy=\"test_strategy\",\n            context={\"test\": True}\n        )\n        \n        # Get confidence\n        confidence, details = confidence_mgr.get_current_confidence(\"TEST\")\n        print(f\"✅ Confidence Manager: {confidence:.2f} confidence\")\n        \n    except Exception as e:\n        print(f\"❌ Confidence Manager: {e}\")\n    \n    # Test 2: Real-time Monitor\n    try:\n        from src.core.realtime_monitor import RealtimeMarketMonitor\n        rt_monitor = RealtimeMarketMonitor(confidence_mgr)\n        \n        rt_monitor.add_symbol(\"TEST.NS\", 100.0)\n        rt_monitor.update_symbol_data(\"TEST.NS\", 101.0, 50000)\n        \n        state = rt_monitor.get_realtime_state(\"TEST.NS\")\n        print(f\"✅ Realtime Monitor: Tracking {state.symbol if state else 'no symbols'}\")\n        \n    except Exception as e:\n        print(f\"❌ Realtime Monitor: {e}\")\n    \n    # Test 3: Regime Weighting\n    try:\n        from src.core.regime_weighting import RegimeAwareWeightingSystem\n        weighting_sys = RegimeAwareWeightingSystem(confidence_mgr)\n        \n        weights = weighting_sys.get_strategy_weights()\n        print(f\"✅ Regime Weighting: {len(weights)} strategies weighted\")\n        \n    except Exception as e:\n        print(f\"❌ Regime Weighting: {e}\")\n    \n    # Test 4: Data Risk Mitigator\n    try:\n        from src.core.data_risk_mitigator import DataSourceRiskMitigator\n        risk_mitigator = DataSourceRiskMitigator()\n        \n        report = risk_mitigator.get_data_quality_report()\n        print(f\"✅ Data Risk Mitigator: {len(report['source_metrics'])} sources tracked\")\n        \n    except Exception as e:\n        print(f\"❌ Data Risk Mitigator: {e}\")\n\ndef test_market_detector():\n    \"\"\"Test market detector\"\"\"\n    \n    print(\"\\n🎯 Testing Market Detector\")\n    print(\"=\" * 30)\n    \n    try:\n        from src.strategies.market_detector import EnhancedMarketDetector\n        \n        detector = EnhancedMarketDetector()\n        print(\"✅ Market detector initialized\")\n        \n        # This might take a moment as it fetches real data\n        print(\"📡 Getting market state (may take 10-15 seconds)...\")\n        market_state = detector.get_current_market_state()\n        \n        print(f\"✅ Market State:\")\n        print(f\"   Direction: {market_state.direction.value}\")\n        print(f\"   Confidence: {market_state.confidence:.2f}\")\n        print(f\"   Gap: {market_state.gap_type.value} ({market_state.gap_size_pct:.2f}%)\")\n        print(f\"   Volatility: {market_state.volatility_regime.value}\")\n        print(f\"   Momentum: {market_state.momentum_score:.1f}\")\n        \n        return True\n        \n    except Exception as e:\n        print(f\"❌ Market Detector: {e}\")\n        import traceback\n        traceback.print_exc()\n        return False\n\ndef test_simple_signal():\n    \"\"\"Test with a simple signal\"\"\"\n    \n    print(\"\\n📊 Testing Signal Processing\")\n    print(\"=\" * 30)\n    \n    try:\n        from src.core.models import ScreenerSignal\n        \n        # Create a simple test signal\n        signal = ScreenerSignal(\n            symbol=\"RELIANCE.NS\",\n            trend=\"BULLISH\",\n            score=75.0,\n            current_price=2500.0,\n            volume=1000000,\n            timestamp=datetime.now()\n        )\n        \n        print(f\"✅ Created signal for {signal.symbol}\")\n        print(f\"   Trend: {signal.trend}\")\n        print(f\"   Score: {signal.score}\")\n        print(f\"   Price: ₹{signal.current_price:.2f}\")\n        \n        return signal\n        \n    except Exception as e:\n        print(f\"❌ Signal Creation: {e}\")\n        return None\n\ndef main():\n    \"\"\"Main test function\"\"\"\n    \n    print(\"🚀 Adaptive Trading System - Core Component Test\")\n    print(\"=\" * 50)\n    print(f\"📅 Date: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\")\n    print()\n    \n    # Test core components\n    test_core_components()\n    \n    # Test market detector\n    detector_works = test_market_detector()\n    \n    # Test signal processing\n    signal = test_simple_signal()\n    \n    print(\"\\n📝 Test Summary\")\n    print(\"=\" * 30)\n    print(f\"✅ Core components: Tested\")\n    print(f\"{'✅' if detector_works else '❌'} Market detector: {'Working' if detector_works else 'Issues'}\")\n    print(f\"{'✅' if signal else '❌'} Signal processing: {'Working' if signal else 'Issues'}\")\n    \n    if detector_works and signal:\n        print(\"\\n🎉 Core system validation: PASSED\")\n        print(\"\\nNext steps:\")\n        print(\"   1. Run: python test_adaptive_live.py --duration 5\")\n        print(\"   2. Test with real market data during market hours\")\n        print(\"   3. Monitor confidence decay and regime changes\")\n    else:\n        print(\"\\n⚠️ Core system validation: PARTIAL\")\n        print(\"Some components have issues but basic functionality works\")\n\nif __name__ == \"__main__\":\n    main()"